#include <bits/stdc++.h>

using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    int ans = 0;
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                if (j - i == k - j and s[i] == 'A' and s[j] == 'B' and s[k] == 'C') ++ans;
            }
        }
    }
    cout << ans << endl;
}

s = input()
n = len(s)
ans = 0

for i in range(n):
  for j in range(i + 1, n):
    for k in range(j + 1, n):
      if j - i == k - j and s[i] == 'A' and s[j] == 'B' and s[k] == 'C':
        ans += 1

print(ans)
